 @SpringBootConfiguration @EnableAutoConfiguration @Import({SeguridadInstitucional.class,NucleoController.class,NucleoU2Controller.class,cl.nexbyte.siger.institucional.notificaciones.NotificacionesController.class,ErroresTecnicos.class,JsonEstricto.class,AvisosNucleoHttpTest.Fixture.class}) static class Application{}
